using namespace std;

class Solution {
public:
    int minRepairCost(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> dist(n, INT_MAX);
        dist[0] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
        pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;
            if (u == n - 1) return d;
            for (auto [v, cost] : adj[u]) {
                if (d + cost < dist[v]) {
                    dist[v] = d + cost;
                    pq.push({d + cost, v});
                }
            }
        }
        return dist[n - 1] == INT_MAX ? -1 : dist[n - 1];
    }
};

import java.util.*;

class Solution {
    public int minRepairCost(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, 0});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > dist[u]) continue;
            if (u == n - 1) return d;
            for (int[] edge : adj.get(u)) {
                int v = edge[0], cost = edge[1];
                if (d + cost < dist[v]) {
                    dist[v] = d + cost;
                    pq.offer(new int[]{d + cost, v});
                }
            }
        }
        return dist[n - 1] == Integer.MAX_VALUE ? -1 : dist[n - 1];
    }
}

var minRepairCost = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, cost] of edges) {
        adj[u].push([v, cost]);
        adj[v].push([u, cost]);
    }
    const dist = new Array(n).fill(Infinity);
    dist[0] = 0;
    const pq = [[0, 0]];
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (d > dist[u]) continue;
        if (u === n - 1) return d;
        for (const [v, cost] of adj[u]) {
            if (d + cost < dist[v]) {
                dist[v] = d + cost;
                pq.push([d + cost, v]);
            }
        }
    }
    return dist[n - 1] === Infinity ? -1 : dist[n - 1];
};
